import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Cdp8-jB6.js";const m=JSON.parse('{"title":"Accessibility statement","description":"","frontmatter":{},"headers":[],"relativePath":"accessibility.md","filePath":"accessibility.md"}'),r={name:"accessibility.md"};function i(n,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="accessibility-statement" tabindex="-1">Accessibility statement <a class="header-anchor" href="#accessibility-statement" aria-label="Permalink to &quot;Accessibility statement&quot;">​</a></h1><p><em>Orrery · target conformance: <strong>WCAG 2.1 Level AA</strong> · last reviewed 2026-07-09 · tracked in RFC-031 / ADR-025</em></p><p>Orrery is a canvas- and WebGL-heavy solar-system explorer, which is historically the <em>hardest</em> kind of web app to make accessible. We treat accessibility as a first-class requirement, not an afterthought, and this statement is an honest account of where we conform, where we don&#39;t yet, and how to reach us.</p><h2 id="conformance-target" tabindex="-1">Conformance target <a class="header-anchor" href="#conformance-target" aria-label="Permalink to &quot;Conformance target&quot;">​</a></h2><p>We target <strong>WCAG 2.1 Level AA</strong>. The app is built to be operated with <strong>keyboard alone</strong>, by a <strong>screen reader</strong>, and by a <strong>TV D-pad remote</strong> — one shared interaction model (a remote is a keyboard: ←→↑↓ + Enter/Back), so a fix for one surface is a fix for all three.</p><h2 id="what-s-supported" tabindex="-1">What&#39;s supported <a class="header-anchor" href="#what-s-supported" aria-label="Permalink to &quot;What&#39;s supported&quot;">​</a></h2><p><strong>Keyboard &amp; remote — everything is reachable without a mouse.</strong></p><ul><li>Every interactive control is keyboard-operable (WCAG 2.1.1) with no keyboard traps (2.1.2).</li><li>The top navigation is a <strong>roving toolbar</strong> — one Tab stop, ← → / D-pad move across it.</li><li>Long lists and grids (missions, fleet, posters, station modules, surface sites) use <strong>roving tabindex</strong> so arrows / the D-pad move <em>within</em> the group instead of tabbing through every item (2.4.3 Focus order).</li><li><strong>Canvas objects are reachable by keyboard</strong> — the part ADR-025 originally deferred. Each 3D/2D scene has a DOM index of its selectable objects: the <code>/explore</code> <strong>body index</strong> (Sun, planets, small bodies), the surface <strong>site index</strong> (<code>/moon</code> <code>/mars</code> <code>/earth</code>), and the <code>/iss</code> · <code>/tiangong</code> module lists. Selecting a row does exactly what a canvas click does — no pointer required.</li><li><strong>Visible focus</strong> on every control (2.4.7), thickened further under the TV 10-foot layer.</li></ul><p><strong>Screen readers.</strong></p><ul><li>Landmarks (<code>&lt;nav&gt;</code>, <code>&lt;main&gt;</code>, complementary panels), honest <code>aria-label</code>s on every canvas describing what it shows and how to reach details, WAI-ARIA <strong>tabs</strong> and <strong>radiogroup</strong> patterns on panels and filters, and <code>aria-live</code> regions announcing dynamic data and load failures (4.1.2, 4.1.3).</li></ul><p><strong>Motion &amp; contrast.</strong></p><ul><li><strong>Reduced motion</strong> (2.3.3, 2.2.2): <code>prefers-reduced-motion: reduce</code> stops all <em>unsolicited</em> motion — auto-orbit, auto-play, auto-rotate — while user-initiated motion still works.</li><li><strong>High-contrast mode</strong> toggle in the nav.</li></ul><p><strong>Targets &amp; internationalisation.</strong></p><ul><li>Interactive targets meet the 44 × 44 px minimum (2.5.5); dense diagrams use expanded invisible hit-pads.</li><li>14 locales, browser-detected, including a right-to-left language (Arabic).</li></ul><h2 id="known-limitations-and-how-we-mitigate-them" tabindex="-1">Known limitations (and how we mitigate them) <a class="header-anchor" href="#known-limitations-and-how-we-mitigate-them" aria-label="Permalink to &quot;Known limitations (and how we mitigate them)&quot;">​</a></h2><ul><li><strong>3D scenes are pointer-driven for <em>manipulation</em></strong> (orbit / pan / pinch-zoom). We do <strong>not</strong> claim keyboard camera control yet — instead, every <em>object</em> those scenes contain is selectable from the DOM indexes above, and every fact is available in the panels. So the content is fully reachable; free-flying the camera by keyboard is future work (RFC-031 S4).</li><li><strong>Screen-reader narration of the live 3D view</strong> is limited to the honest canvas label + the object indexes; we don&#39;t read every object&#39;s changing position aloud (it floods). Focusing an index row announces that object.</li><li>We have <strong>not</strong> completed a full third-party audit; conformance is self-assessed against automated (axe-core) + manual keyboard / screen-reader / contrast testing.</li></ul><h2 id="assistive-technologies-tested" tabindex="-1">Assistive technologies tested <a class="header-anchor" href="#assistive-technologies-tested" aria-label="Permalink to &quot;Assistive technologies tested&quot;">​</a></h2><p>Keyboard-only navigation and VoiceOver (macOS/iOS) on the latest Safari and Chrome; Android TalkBack and a D-pad remote on the Google-TV build.</p><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><p>Found a barrier? Please open an issue at <strong><a href="https://github.com/chipi/orrery/issues" target="_blank" rel="noreferrer">github.com/chipi/orrery/issues</a></strong> with the page, what you were trying to do, and your assistive tech + browser. Accessibility regressions are treated as bugs, not enhancements.</p><hr><p><em>This statement is versioned with the code (<code>docs/accessibility.md</code>) and updated as conformance changes. See RFC-031 for the roadmap and ADR-025 for the original tier-1 contract.</em></p>',22)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
